/**
 * 公共收益统计 → 列表页
 * mode==='month' 带当月备案区间；历史累计/chart 不带时间（bug 6409：累计跳转不要带时间）。
 * 列表仅展示已备案（biz_state=2）数据，与首页统计口径一致；否则会带出待提交/审核中记录
 * （bug 6409 复核：跳转后不应显示待提交/审核中，只显示已备案）。
 * 注意：部分环境 BIZ_STATE 字典 1/2 文案与后端编码颠倒，故只取字典 key（biz_state=2），
 * 不走 BIZ_STATE 文案映射。
 */
export const BENEFIT_STAT_NAV = {
  org: {
    filePath: 'benefit/pubManagementOrg/index',
    // 开户主体数：仅统计状态正常（accountState=0）且已备案（biz_state=2）；仅当月额外限备案区间
    params: (mode) => (mode === 'month'
      ? { ...monthRecordedParams(), accountState: '0' }
      : { accountState: '0', bizState: '2' })
  },
  account: {
    filePath: 'benefit/pubRegulatoryAccount/index',
    // 监管账户数：仅已备案；累计/图表不加时间，当月加备案区间
    params: (mode) => (mode === 'month' ? monthRecordedParams() : { bizState: '2' })
  },
  protocol: {
    filePath: 'benefit/pubRegulatoryAgreement/index',
    // 已签托管协议专户数：仅已备案；累计/图表不加时间，当月加备案区间
    params: (mode) => (mode === 'month' ? monthRecordedParams() : { bizState: '2' })
  },
  fund: {
    filePath: 'benefit/pubBankAccountBalance/index',
    params: () => ({})
  }
}

